-- WoW Forever: quest objects that hold the quest items live quests need (herbs, chests, tablets, crystals, rock piles) and that
-- our world does not have. Name, model and map spots from Wowhead's WoW Forever object pages, which item each one holds
-- from the item pages (www.wowhead.com/forever, read 2026-11-20). Settings copied from our own plain quest chest (Snowdrift
-- 629596: open on click, used up, only for players on the quest); each holds its quest item. Spawns: Wowhead map spot turned
-- into world coordinates with the per-zone fit (EG Link CC BY 4.0; NorgannonDB GPL-3.0 pairs for Azshara), height from our
-- own spawns (nearest within 12 yd on level ground, else 3+ within 25 yd less than 2 yd apart). Objects with no usable spot
-- get template and loot only, for a sniff to place. Respawn 120 s, orientation 0 (ESTIMATED). Safe to run again.
DELETE FROM `gameobject` WHERE `guid` BETWEEN 47500100 AND 47501099;
DELETE FROM `gameobject_template` WHERE `entry` IN (422911,423569,424002,441222,461639,507731,507746,524260,524284,524298,524759,525677,570888,570890,571511,584729,587299,612179,613761,613764,617262,617265,618822,629472,648579,649094,649097,649099,649100,649103) AND `VerifiedBuild`=-1;
DELETE FROM `gameobject_loot_template` WHERE `Entry` IN (422911,423569,122215,441222,461639,507731,507746,524260,524284,524298,524759,525677,570888,570890,571511,584729,136879,612179,613761,613764,617262,617265,618822,629472,648579,649094,649097,649099,649100,649103) AND `Comment`='Wowhead WoW Forever';
UPDATE `gameobject_template` SET `Data8`=97047 WHERE `entry`=424002 AND `Data8`=0;
UPDATE `gameobject_template` SET `Data8`=93044 WHERE `entry`=587299 AND `Data8`=0;
